package com.smarthub.plus;
import android.accessibilityservice.AccessibilityService;
import android.graphics.*;
import android.os.*;
import android.view.accessibility.AccessibilityNodeInfo;
/** Programme art and channel branding have independent availability and cache identities. */
final class NativeGuideArtwork {
 private static final class Selection {
  String channel="",channelId="",title="",time="";Rect logo=new Rect(),image=new Rect(),screen=new Rect();int window;
  String key(){return channelId+"|"+channel+"|"+title+"|"+time+"|"+image;}
  String logoKey(){return channelId+"|"+channel+"|"+logo+"|"+System.currentTimeMillis()/86400000L;}
  boolean hasArt(){return !title.isEmpty()&&image.width()>=100&&image.height()>=100;}
  boolean hasLogo(){return !channelId.isEmpty()&&logo.width()>=12&&logo.height()>=12;}
 }
 private final AccessibilityService service;private boolean busy,display;private long retry;private String savedArt="",savedLogo="";
 NativeGuideArtwork(AccessibilityService s){service=s;}
 private Selection selection(){AccessibilityNodeInfo root=TvWindowRoot.find(service);if(root==null)return null;try{return selection(root);}finally{root.recycle();}}
 private Selection selection(AccessibilityNodeInfo root){if(root==null||!SatelliteUiParser.DEFAULT_PACKAGE.contentEquals(root.getPackageName()))return null;Selection s=new Selection();s.window=root.getWindowId();root.getBoundsInScreen(s.screen);collect(root,s,0);if(s.image.width()>0||s.logo.width()>0)status("EPG views · selected="+!s.channel.isEmpty()+" · programme="+s.hasArt());if(!s.channel.isEmpty()&&(s.hasArt()||s.hasLogo()))return s;Selection banner=new Selection();banner.window=root.getWindowId();root.getBoundsInScreen(banner.screen);java.util.Map<String,String> fields=new java.util.HashMap<>();collectBanner(root,banner,fields,0,new int[]{0});SatelliteState state=SatelliteUiParser.parse(fields,System.currentTimeMillis(),java.time.ZoneId.of(service.getSharedPreferences("smarthub",0).getString("tv_epg_timezone","Asia/Baghdad")));if(state==null||state.title.isEmpty()||state.startMs<=0||!banner.hasArt())return null;banner.channel=state.channelName;banner.channelId=state.channelId;banner.title=state.title;banner.time=state.startMs+"|"+state.endMs;return banner;}
 private void collect(AccessibilityNodeInfo n,Selection s,int depth){if(depth>24||n.isPassword()||n.isEditable())return;String id=NativeTvUi.shortId(n);if(n.isVisibleToUser()){String value=n.getText()==null?"":n.getText().toString().trim();if(id.equals("tv_program_name")&&n.isSelected())s.channel=value;else if(id.equals("tv_program_index")&&n.isSelected()&&value.matches("[0-9]{1,7}"))s.channelId="Aurum:"+Integer.parseInt(value);else if(id.equals("epg_program_icon")&&n.isSelected())n.getBoundsInScreen(s.logo);else if(id.equals("tv_epg_detail_title"))s.title=value;else if(id.equals("tv_epg_detail_time"))s.time=value;else if(id.equals("iv_epg_detail"))n.getBoundsInScreen(s.image);}for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo c=n.getChild(i);if(c!=null)try{collect(c,s,depth+1);}finally{c.recycle();}}}
 private void collectBanner(AccessibilityNodeInfo n,Selection s,java.util.Map<String,String> fields,int depth,int[] count){if(depth>24||count[0]++>600||n.isPassword()||n.isEditable())return;if(n.isVisibleToUser()){String id=NativeTvUi.shortId(n);if(SatelliteUiParser.VIEW_IDS.contains(id)&&n.getText()!=null){fields.put(id,n.getText().toString());if(id.equals("mtv_info_current_epg"))s.title=n.getText().toString();}if(id.equals("iv_program_poster")||id.equals("iv_poster"))n.getBoundsInScreen(s.image);}for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo child=n.getChild(i);if(child!=null)try{collectBanner(child,s,fields,depth+1,count);}finally{child.recycle();}}}
 private void status(String value){service.getSharedPreferences("smarthub",0).edit().putString("epg_art_capture_status",value).apply();}
 void observe(AccessibilityNodeInfo root){if(Build.VERSION.SDK_INT<34||busy||SystemClock.elapsedRealtime()<retry)return;final Selection target=selection(root);if(target==null)return;boolean art=target.hasArt()&&!savedArt.equals(target.key()),logo=target.hasLogo()&&!savedLogo.equals(target.logoKey());if(!art&&!logo)return;busy=true;retry=SystemClock.elapsedRealtime()+2500;
  AccessibilityService.TakeScreenshotCallback callback=new AccessibilityService.TakeScreenshotCallback(){
   public void onFailure(int code){busy=false;status("Android screenshot error "+code);if(code==1)display=true;}
   public void onSuccess(AccessibilityService.ScreenshotResult result){Bitmap hardware=null;try{Selection current=selection();if(current==null||!current.key().equals(target.key())||!current.logoKey().equals(target.logoKey()))return;hardware=Bitmap.wrapHardwareBuffer(result.getHardwareBuffer(),result.getColorSpace());if(hardware==null)return;
    if(logo){Bitmap badge=crop(hardware,target.logo,target.screen);try{if(contrast(badge)){CHMAXIntegration.saveObservedLogo(service,target.channelId,target.channel,badge);savedLogo=target.logoKey();}}finally{if(badge!=null)badge.recycle();}}
    if(art){Bitmap image=crop(hardware,target.image,target.screen);try{if(usable(image)){EpgArtwork.saveGuide(service,target.channel,target.title,image);savedArt=target.key();}}finally{if(image!=null)image.recycle();}}
   }catch(Exception e){status("Native image unavailable · "+e.getClass().getSimpleName());}finally{if(hardware!=null)hardware.recycle();result.getHardwareBuffer().close();busy=false;}}
  };if(display)service.takeScreenshot(android.view.Display.DEFAULT_DISPLAY,service.getMainExecutor(),callback);else service.takeScreenshotOfWindow(target.window,service.getMainExecutor(),callback);
 }
 private static Bitmap crop(Bitmap full,Rect rect,Rect screen){if(screen.width()<=0||screen.height()<=0)return null;int x=Math.max(0,(rect.left-screen.left)*full.getWidth()/screen.width()),y=Math.max(0,(rect.top-screen.top)*full.getHeight()/screen.height()),w=Math.min(full.getWidth()-x,rect.width()*full.getWidth()/screen.width()),h=Math.min(full.getHeight()-y,rect.height()*full.getHeight()/screen.height());if(w<12||h<12)return null;Bitmap region=Bitmap.createBitmap(full,x,y,w,h);Bitmap copy=region.copy(Bitmap.Config.ARGB_8888,false);if(region!=full)region.recycle();return copy;}
 private static boolean contrast(Bitmap image){if(image==null)return false;int low=255,high=0;for(int y=0;y<image.getHeight();y+=4)for(int x=0;x<image.getWidth();x+=4){int p=image.getPixel(x,y),v=(Color.red(p)+Color.green(p)+Color.blue(p))/3;low=Math.min(low,v);high=Math.max(high,v);}return high-low>=45;}
 static boolean usable(Bitmap image){if(image==null)return false;int[] bins=new int[32];int total=0,colored=0;for(int y=0;y<image.getHeight();y+=4)for(int x=0;x<image.getWidth();x+=4){int p=image.getPixel(x,y),r=Color.red(p),g=Color.green(p),b=Color.blue(p);bins[(r*3+g*6+b)/10/8]++;if(Math.max(r,Math.max(g,b))-Math.min(r,Math.min(g,b))>35)colored++;total++;}int distinct=0;for(int count:bins)if(count>total/200)distinct++;return distinct>=18||distinct>=8&&colored>total/12;}
}
